from pathlib import Path
from html import escape as esc
import json, re
import data as d
from data import *

ROOT=Path(__file__).resolve().parents[1]
def e(s):return esc(str(s),quote=True)
def c(k):return e(COPY[k])
def button(text,attrs='',cls='button'):return f'<button class="{cls}" {attrs}>{text}</button>'
def photo(char,expression=None,prefix=''):
    rel=char['portrait'] if expression in (None,1) else ''
    available=bool(rel and (ROOT/rel).is_file())
    return f'<div class="portrait" style="--person:{char["color"]}" data-portrait><div class="portrait-placeholder" {"hidden" if available else ""}><span>{char["code"]}</span><p>{c("portrait_empty")}</p></div>'+ (f'<img src="{prefix+e(rel)}" alt="{e(char["name"])}" fetchpriority="high">' if available else '')+'</div>'
def banner(code,prefix='',extra=''):
    return f'<div class="room-view {extra}"><img data-scene src="{prefix}{d.CONFIG["BACKGROUND_DIR"]}/{code}.webp" alt="" fetchpriority="high"><div class="view-shade"></div><span class="view-corner a"></span><span class="view-corner b"></span></div>'
def heading(label,title,side=''):
    return f'<div class="room-heading"><div><span class="eyebrow">{label}</span><h1>{e(title)}</h1></div>{side}</div>'
def entrance():
    return f'''<div class="entry-scene">{banner('G')}<div class="rain" aria-hidden="true"></div><div class="lantern" aria-hidden="true"><i></i></div><section class="door"><span class="eyebrow">VEILHAUN · BACK ALLEY MASSAGE</span><span class="hanging-sign" data-status>{c('open')}</span><div class="door-sign"><span class="small-rule"></span><h1>{e(d.CONFIG['SHOP_NAME'])}</h1><p>{e(d.CONFIG['TITLE'])}</p><span class="small-rule"></span></div><p class="entry-age"><b>19+</b> {c('age')}</p>{button(c('enter')+' <span aria-hidden="true">↗</span>','id="enter"','button door-handle')}<small>{c('no_age')}</small><p class="author">{c('author')} {e(d.CONFIG['AUTHOR'])}</p></section></div>'''
def home():
    menu=''.join(f'<li><span>{e(n)}<small>{e(t)}</small></span><b>{e(p)}</b></li>' for n,p,t in MENUS)
    reservations=''.join(f'<li><time>{e(r.get("time",""))}</time><span>{e(r.get("name",""))}</span><span>{e(r.get("menu",""))}</span></li>' for r in d.CONFIG['RESERVATIONS'])
    if not reservations: reservations=f'<li class="empty-reservation">{c("no_reservation")}</li>'+''.join(f'<li aria-label="빈 예약 줄"><span>·· : ··</span><span>······</span><span>······</span></li>' for _ in range(3))
    notes=''.join(f'<li class="pinned-note"><i aria-hidden="true"></i>{e(x)}</li>' for x in d.RUMORS[:4])
    rep=''.join(f'<li class="{"current" if i==0 else ""}"><span>{i+1:02}</span>{e(x)}</li>' for i,x in enumerate(REPUTATION))
    return banner('R')+heading('RECEPTION',COPY['today'],'<div class="date-stamp"><time data-date></time><span data-status></span></div>')+f'''<div class="reception-desk"><section class="ledger paper"><div class="paper-top"><span>01 / RECEPTION</span><span data-period></span></div><h2>{c('reservation')}</h2><p class="muted" data-hours></p><ul class="reservation-list">{reservations}</ul><div class="reputation"><h3>{c('reputation')}</h3><ol>{rep}</ol></div><span class="paper-page">01</span></section><section class="menu-board"><span class="eyebrow">THE HOUSE MENU</span><h2>{c('price_title')}</h2><ul>{menu}</ul><p class="handwriting">{c('menu_note')}</p></section><button class="partition" id="partition" aria-describedby="voice"><span class="partition-lines" aria-hidden="true"></span><span class="eyebrow">BEYOND THE CURTAIN</span><strong>{c('partition')}</strong><span>{c('partition_touch')}</span><q id="voice" aria-live="polite">{c('partition_hint')}</q></button></div><section class="rumor-wall"><h2>{c('rumor_wall')}</h2><ul>{notes}</ul></section>'''
def thumbnail(ch):
    rel=ch['thumbnail']
    if (ROOT/rel).is_file():return f'<img class="person-thumb" src="{e(rel)}" alt="" loading="lazy" width="46" height="60">'
    return f'<span class="person-index">{ch["code"]}</span>'
def characters():
    ch=d.CHARACTERS[0]
    people=''.join(f'<button class="person-row {"selected" if i==0 else ""}" data-person="{i}" data-group="{e(x["group"])}" aria-pressed="{str(i==0).lower()}" style="--person:{x["color"]}">{thumbnail(x)}<span><strong>{e(x["name"])}</strong><small>{e(x["role"])}</small><small>◇ {e(x["knots"].split(" / ")[0])} · {e(x["boundary"])}</small></span><span aria-hidden="true">↗</span></button>' for i,x in enumerate(d.CHARACTERS))
    return banner('W')+heading('WAITING ROOM','대기실')+f'''<div class="waiting-layout"><section class="guest-list"><div class="tabs" role="group" aria-label="인물 분류">{button(c('staff'),'data-filter="직원" aria-pressed="true"','tab active')}{button(c('guests'),'data-filter="손님" aria-pressed="false"','tab')}</div>{people}</section><section class="character-stage" id="selected-person" style="--person:{ch['color']}">{photo(ch)}<div class="character-caption"><span class="eyebrow" id="person-meta">{e(ch['race'])} · {e(ch['age'])} · {e(ch['role'])}</span><h2 id="person-name">{e(ch['name'])}</h2><blockquote id="person-hook">“{e(ch['hook'])}”</blockquote><a class="button" id="chart-link" href="char/{ch['slug']}.html">{c('chart')} <span>↗</span></a></div></section></div>'''
def chart(ch):
    ci=d.CHARACTERS.index(ch)
    prev_ch=d.CHARACTERS[(ci-1)%len(d.CHARACTERS)]
    next_ch=d.CHARACTERS[(ci+1)%len(d.CHARACTERS)]
    reactions=ch['reactions'].split(' / ')
    react=[ch['collapse'],reactions[0],reactions[1].split(': ',1)[-1],reactions[2].split(': ',1)[-1]]
    reaction_html=''.join(f'<div><dt>{c(k)}</dt><dd>{e(v)}</dd></div>' for k,v in zip(['collapse','stop','ask','jealous'],react))
    thumbs=''.join(f'<button data-expression="{i}" class="expression {"active" if i==1 else ""}" aria-pressed="{str(i==1).lower()}"><span>{i:02}</span>{e(x)}</button>' for i,x in enumerate(EXPRESSIONS,1))
    bounds=''.join(f'<li class="{"unlocked" if i<(2 if ch["code"]=="E" else 1) else "locked"}"><span>{"◇" if i<(2 if ch["code"]=="E" else 1) else "▧"}</span>{e(x)}</li>' for i,x in enumerate(BOUNDARIES))
    rel=''.join(f'<li>{e(x)}</li>' for x in d.RELATIONS if ch['name'] in x)
    return f'''<div class="chart-layout" style="--person:{ch['color']}"><aside class="chart-stage"><nav class="character-nav" aria-label="인물 넘기기"><a href="{prev_ch['slug']}.html">← {e(prev_ch['name'])}</a><a href="{next_ch['slug']}.html">{e(next_ch['name'])} →</a></nav>{photo(ch,1,'../')}<div class="chart-person"><span class="eyebrow">{e(ch['race'])} · {ch['age']} · {e(ch['group'])}</span><h1>{e(ch['name'])}</h1><p>{e(ch['role'])}</p></div><div class="expression-controls">{button('←','id="expr-prev" aria-label="'+COPY['prev']+'"','square')}<span id="expression-title">01 · {e(EXPRESSIONS[0])}</span>{button('→','id="expr-next" aria-label="'+COPY['next']+'"','square')}</div><div class="expression-strip" aria-label="감정 탭">{thumbs}</div><div id="variant-thumbs" aria-label="감정 변형"></div><p class="key-hint">{c('expression_help')}</p></aside><article class="chart-paper paper"><div class="paper-top"><span>CHART / {ch['code']}</span><a href="../characters.html">{c('staff')+' · '+c('guests')} ↗</a></div><div class="chart-heading"><h2>{e(ch['name'])}</h2><span class="stamp">{e(ch['boundary'])}</span></div><blockquote>“{e(ch['hook'])}”</blockquote><p class="chart-description">{e(ch['description'])}</p><section class="map-section"><div><h3>{c('knot_map')}</h3><p>{e(ch['knots'])}</p><div class="tabs">{button(c('front'),'data-facing="front" aria-pressed="true"','tab active')}{button(c('back'),'data-facing="back" aria-pressed="false"','tab')}</div><p class="map-label" id="knot-label" aria-live="polite">{c('knots')}</p><small>○ {c('sensitive')}</small></div><div class="body-map"><svg viewBox="0 0 200 300" aria-label="결 자리 실루엣" role="img"><circle cx="100" cy="46" r="23"/><path d="M85 70 Q60 74 52 94 L36 163 Q37 174 47 169 L68 112 L70 174 L59 265 Q63 279 74 269 L99 193 L125 269 Q136 277 140 265 L129 174 L131 112 L153 169 Q164 174 164 161 L147 94 Q137 74 115 70Z"/></svg><div id="map-dots"></div></div></section><section><h3>{c('boundary_title')}</h3><ol class="boundary-track">{bounds}</ol></section><dl class="reactions">{reaction_html}</dl><div class="chart-quotes">{''.join('<blockquote>“'+e(q)+'”</blockquote>' for q in ch['quotes'])}</div><details><summary>{c('appearance')} · {c('speech')}</summary><p>{e(ch['appearance'])}</p><p>{e(ch['speech'])}</p></details><section class="relationships"><h3>{c('relations')}</h3><ul>{rel}</ul></section><span class="paper-page">{ch['code']} / 05</span></article></div>'''
def rules():
    depths=''.join(f'<li><b>{i:02}</b><div><h3>{e(n)}</h3><p>{e(t)}</p></div></li>' for i,(n,t) in enumerate(DEPTHS,1))
    heat=''.join(f'<button class="heat-step {"active" if i==0 else ""}" data-heat="{i}" aria-pressed="{str(i==0).lower()}"><i class="flame" style="--flame:{1+i*.15}" aria-hidden="true"></i><span>{e(x)}</span></button>' for i,x in enumerate(HEAT))
    bottles=''.join(f'<button class="bottle" data-oil="{key}" aria-label="{c(label)}"><span class="bottle-neck"></span><span class="bottle-glass"><span>{c(label) if key!="unknown" else "?"}</span></span></button>' for key,label in [('calm','calm'),('warm','warm'),('unknown','unknown')])
    return banner('P')+heading('STILL ROOM',COPY['note_title'])+f'''<div class="oil-shelf">{bottles}<p id="oil-note" aria-live="polite">{c('oil_shelf')}</p></div><article class="notebook paper"><section><span class="eyebrow">I / NOTES ON KNOTS</span><h2 class="handwriting">{c('knots_title')}</h2><p>{c('knots_definition')}</p><p class="ink-note">{c('knots_progress')}</p><h3>{c('depth')}</h3><ol class="depth-list">{depths}</ol></section><section><span class="eyebrow">II / OBSERVATIONS</span><h2 class="handwriting">{c('heat')}</h2><div class="heat-scale">{heat}</div><h3>{c('boundary_title')}</h3><ol class="numbered-steps">{''.join('<li>'+e(x)+'</li>' for x in BOUNDARIES)}</ol><h3>{c('relation_title')}</h3><p class="relation-stages">{' → '.join(RELATION_STAGES)}</p><p class="currency">{c('currency')}</p></section></article>'''
def treatment():
    link=f'<a class="button" href="{e(d.CONFIG["MASA_URL"])}">{c("treatment_cta")} ↗</a>' if d.CONFIG['MASA_URL'] else f'<span class="closed-sign">{c("coming")}</span>'
    return heading('TREATMENT',COPY['treatment_title'])+f'<section class="treatment-room">{banner("T")}<div class="curtain left"></div><div class="curtain right"></div><div class="curtain-sign"><p>{c("treatment_note")}</p>{link}</div></section>'
def city():
    places=''.join(f'<button class="place-row {"active" if i==0 else ""}" data-place="{i}" aria-pressed="{str(i==0).lower()}"><span>{i+1:02}</span>{e(p["name"])}<span>↗</span></button>' for i,p in enumerate(PLACES))
    return heading('VEILHAUN',COPY['city_note'],f'<p class="room-subtitle">{c("city_intro")}</p>')+f'''<div class="city-layout"><nav class="places" aria-label="도시 장소">{places}<p class="key-hint">{c('city_help')}</p></nav><section class="city-window">{banner('M')}<article class="city-info paper"><span class="eyebrow" id="place-number">01 / VEILHAUN</span><h2 id="place-name">{e(PLACES[0]['name'])}</h2><p id="place-text">{e(PLACES[0]['text'])}</p><p id="place-guest"></p></article></section></div>'''
def start():
    modes=''.join(f'<button class="mode-slot {"active" if i==0 else ""}" data-mode="{key}" aria-pressed="{str(i==0).lower()}"><span class="eyebrow">0{i+1}</span><strong>{e(name)}</strong><span>{e(desc)}</span></button>' for i,(key,name,desc) in enumerate(MODES))
    link=f'<a class="button" href="{e(d.CONFIG["CRACK_URL"])}">{c("crack_cta")} ↗</a>' if d.CONFIG['CRACK_URL'] else f'<span class="closed-sign">{c("crack_empty")}</span>'
    return banner('R')+heading('OPENING',COPY['opening_title'])+f'''<div class="opening-layout"><section class="mode-list">{modes}<form id="free-form" hidden><p>{c('free_note')}</p><label>{c('day_count')}<input name="day" type="number" min="0" max="99999"></label><label>{c('money')}<input name="money" maxlength="120"></label><label>{c('reputation')}<select name="rep">{''.join('<option>'+e(x)+'</option>' for x in REPUTATION)}</select></label><label>{c('known')}<textarea name="relations" maxlength="1000"></textarea></label>{button(c('copy'),'type="submit"')}<output id="copy-status" aria-live="polite"></output><textarea id="copy-fallback" aria-label="복사할 출발 상태" readonly hidden></textarea></form></section><article class="sample paper"><span class="eyebrow">FIRST PAGE</span><h2>{c('sample')}</h2><div class="sample-scene"><span>{c('sample_background')}</span></div><div id="prologue"><p class="empty-copy">{c('prologue_empty')}</p></div><div class="sample-labels"><span>{c('sample_narration')}</span><span>{c('sample_portrait')}</span><span>{c('sample_dialogue')}</span></div><h3>{c('sample_status')}</h3><pre>{e(STATUS_TEMPLATE)}</pre><details><summary>{c('play_guide')}</summary><h3>{c('user_note')}</h3><p>{c('unwritten')}</p><h3>{c('shortcuts')}</h3><p>{c('unwritten')}</p></details>{link}</article></div>'''
def write_page(filename,page,body,char=None):
    prefix='../' if '/' in filename else ''
    title=char['name'] if char else (dict((r[0],r[1]) for r in ROOMS).get(page,COPY['entrance']))
    nav=''.join(f'<a href="{prefix}{slug}.html" {"aria-current=\"page\"" if page==slug else ""}><small>{i}</small>{name}</a>' for i,(slug,name,_,_) in enumerate(ROOMS,1))
    period=''.join(button(t['name'],f'data-time="{t["id"]}" aria-pressed="false"','time-button') for t in TIMES)
    payload=dict(config=d.CONFIG,characters=d.CHARACTERS,rumors=d.RUMORS,voices=d.VOICES,places=PLACES,times=TIMES,expressions=EXPRESSIONS,copy=COPY,knots=KNOT_MAP,page=page,character=char['slug'] if char else None,prefix=prefix)
    for ch in payload['characters']:
        ch['availablePortrait']=bool(ch['portrait'] and (ROOT/ch['portrait']).is_file())
        ch['availableExpressions']={}
        ch['gallery']=[[ch['portrait']] if g['start'] is None and ch['availablePortrait'] else [f"{d.CONFIG['CHARACTER_DIR']}/{ch['code']}_{n}.webp" for n in range(g['start'],g['end']+1) if (ROOT/f"{d.CONFIG['CHARACTER_DIR']}/{ch['code']}_{n}.webp").is_file()] if g['start'] is not None else [] for g in EXPRESSION_GROUPS]
    data_json=json.dumps(payload,ensure_ascii=False).replace('</','<\\/')
    bg=dict((x[0],x[3]) for x in ROOMS).get(page,'G')
    preload=f'{prefix}{d.CONFIG["BACKGROUND_DIR"]}/{bg}.webp'
    if char and char['availablePortrait']:preload=prefix+char['portrait']
    guard='' if page=='index' else f'<script src="{prefix}assets/guard.js"></script>'
    html=f'''<!doctype html><html lang="ko" data-time="evening"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#16100c"><meta name="description" content="{e(d.CONFIG['TITLE'])}. 자유교역도시 베일하운, 골목 시술소의 방과 인물."><title>{e(title)} | {e(d.CONFIG['SHOP_NAME'])}</title>{guard}<link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="{prefix}assets/fonts/Pretendard.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="{prefix}{d.CONFIG['BACKGROUND_DIR']}/{bg}.webp" as="image"><link rel="stylesheet" href="{prefix}assets/site.css"><script id="site-data" type="application/json">{data_json}</script><script defer src="{prefix}assets/site.js"></script></head><body class="page-{page}"><a class="skip-link" href="#main">{c('skip')}</a><header class="topbar"><a class="brand" href="{prefix}home.html"><span class="brand-mark" aria-hidden="true">◇</span><span>{e(d.CONFIG['SHOP_NAME'])}<small>VEILHAUN</small></span></a><nav class="room-tabs" aria-label="방">{nav}</nav><div class="utilities"><div class="time-toggle" role="group" aria-label="시간대">{period}</div>{button('♪','id="sound" aria-label="효과음" aria-pressed="false"','utility')}{button('☰','id="menu-open" aria-label="방 안내"','utility')}</div></header><main id="main" tabindex="-1">{body}</main><footer class="site-footer"><span>{e(d.CONFIG['TITLE'])}</span><span>{c('author')} {e(d.CONFIG['AUTHOR'])}</span><span>19+</span></footer><aside class="bell-widget"><div id="rumor-note" class="bell-note" hidden><span class="eyebrow">{c('rumor')}</span><p id="rumor-text" aria-live="polite"></p>{button('×','id="rumor-close" aria-label="소문 쪽지 닫기"','note-close')}</div>{button('<svg viewBox="0 0 40 40" aria-hidden="true"><path d="M8 27h24M11 26c0-14 18-14 18 0M19 10h2v5M6 31h28"/></svg><span>'+c('bell')+'</span>','id="bell" aria-expanded="false"','bell-button')}</aside><dialog id="room-menu"><form method="dialog">{button('×','aria-label="닫기"','dialog-close')}</form><span class="eyebrow">HOUSE DIRECTORY</span><h2>{c('menu')}</h2><nav>{nav}<a href="{prefix}index.html" data-exit><small>7</small>{c('exit')}</a></nav><p>{c('keyboard_help')}</p></dialog></body></html>'''
    if re.search('[\u2014\u2013]',html):raise ValueError('Forbidden dash in '+filename)
    dest=ROOT/filename;dest.parent.mkdir(exist_ok=True);dest.write_text(html,encoding='utf-8')

if __name__=='__main__':
    for page,fn in [('index',entrance),('home',home),('characters',characters),('rules',rules),('treatment',treatment),('city',city),('start',start)]:write_page(page+'.html',page,fn())
    for char in d.CHARACTERS:write_page('char/'+char['slug']+'.html','chart',chart(char),char)
    (ROOT/'.nojekyll').touch()
    print('Built 12 pages. Forbidden dash check passed.')
